content:
cat <<EOF > /work/config.json
{
  "fine_rates": {
    "regular": 0.5,
    "new_release": 1.0,
    "children": 0.25
  },
  "loan_periods": {
    "regular": 14,
    "new_release": 7,
    "children": 21
  },
  "branches": [
    "Central Library",
    "North Branch",
    "South Branch",
    "East Branch",
    "West Branch"
  ],
  "opening_hours": {
    "Monday": "9:00-18:00",
    "Tuesday": "9:00-18:00",
    "Wednesday": "9:00-18:00",
    "Thursday": "9:00-18:00",
    "Friday": "9:00-18:00",
    "Saturday": "10:00-16:00",
    "Sunday": "Closed"
  },
  "max_loans_per_member": 5,
  "reservation_period_days": 3,
  "membership_fee": 15.0,
  "late_fee_max": 25.0,
  "notification_settings": {
    "email_notifications": true,
    "sms_notifications": false,
    "reminder_days_before_due": 2
  },
  "penalties": {
    "lost_book_fee": 30.0,
    "damaged_book_fee": 10.0
  },
  "catalogue_settings": {
    "allow_reservations": true,
    "max_reservations_per_member": 3
  }
}
EOF

